<template><section class="apps-manager"><header><h2>Apps &amp; Workspaces</h2><p>Choose a workspace to manage its connections. Vault is your personal workspace for documents and selected connected material.</p></header>
<nav class="app-actions" aria-label="Workspaces"><button v-for="item in workspaceTabs" :key="item.id" class="usx-btn" :aria-pressed="workspace===item.id" @click="chooseWorkspace(item.id)"><UIcon :name="item.icon" />{{ item.label }}</button></nav>
<section v-if="workspace==='google'"><h3>Google Workspace</h3><p>Connect a Google account and choose supported lists and directions. Direct cloud access requires provider consent and the applicable permissions.</p><ConnectionsPanel connections-only provider-mode="cloud" /></section>
<section v-else-if="workspace==='apple'"><h3>Apple Workspace</h3><template v-if="platform==='macos'"><p>Choose supported local Mac apps and lists. Account and iCloud settings remain in macOS.</p><ConnectionsPanel connections-only provider-mode="local" /></template><p v-else>Local Apple app adapters require a Mac host. No Apple connection is made on this platform.</p></section>
<section v-else-if="workspace==='linux'"><h3>Linux Workspace</h3><p>Evolution and Thunderbird live adapters are not implemented. Use explicit file import/export where supported; no background account sync is claimed.</p></section>
<section v-else><h3>Vault</h3><p>Browse your personal files in the shared Vault sidebar. Connected records below retain their account sources.</p><button class="usx-btn" @click="openVault"><UIcon name="folder_open" />Browse Vault</button><ConnectionsPanel :key="collectionKind" collection-only :initial-kind="collectionKind" /><nav class="app-actions" aria-label="Connected records"><button v-for="kind in ['tasks','contacts','notes','calendar','mail']" :key="kind" class="usx-btn" :aria-pressed="collectionKind===kind" @click="chooseCollection(kind)">{{ kind }}</button></nav></section>
<section class="apps-browser"><h3>Bookmarks and reading lists</h3><p>Import bookmark HTML from Safari, Chrome, Firefox or Edge. Safari exports can include Reading List. This is manual file exchange; your browser owns continuous cloud sync.</p><div class="app-actions"><label for="browser-source">Browser</label><select id="browser-source" v-model="browser"><option value="safari">Safari</option><option value="chrome">Chrome</option><option value="firefox">Firefox</option><option value="edge">Edge</option><option value="browser">Other</option></select><label class="usx-btn" for="browser-export-file"><UIcon name="upload_file" />Import HTML</label><input id="browser-export-file" type="file" accept=".html,.htm,text/html" :disabled="busy" @change="importFile" /><button class="usx-btn" :disabled="busy" @click="exportFile"><UIcon name="download" />Export HTML</button></div><p v-if="message" role="status">{{ message }}</p><p v-if="error" role="alert">{{ error }}</p><div class="app-actions"><button v-for="kind in ['bookmarks','reading_list']" :key="kind" class="usx-btn" :aria-pressed="activeKind===kind" @click="activeKind=kind">{{ kind==='bookmarks'?'Bookmarks / favourites':'Reading list' }} · {{ records.filter(r=>r.kind===kind).length }}</button></div><article v-for="record in records.filter(r=>r.kind===activeKind)" :key="record.id" class="browser-link"><a :href="record.data.url" target="_blank" rel="noopener noreferrer">{{ record.data.title }}</a><small>{{ record.data.folders?.join(' / ') }}</small><label v-if="record.kind==='reading_list'"><input type="checkbox" :checked="record.data.read" @change="markRead(record,($event.target as HTMLInputElement).checked)" />Read locally</label></article></section><section><h3>Recommended apps</h3><p>Maintained for the integration modes shown. App-managed sync does not imply a live uDOS adapter.</p><article v-for="app in apps" :key="app.id" class="recommended-app"><div><h4>{{ app.name }}</h4><small>{{ app.points.join(' · ') }} · {{ app.mode.replaceAll('-',' ') }}</small><p>{{ app.description }}</p></div><a class="usx-btn" :href="app.url" target="_blank" rel="noopener noreferrer">Official site<UIcon name="open_in_new" /></a></article></section></section></template>
<script setup lang="ts">
import { onMounted,ref } from 'vue';import { UCORE_BASE } from '../../api/base';import { computed } from 'vue';import { useShellStore } from '../../stores/shell';import { useRoute,useRouter } from 'vue-router';import ConnectionsPanel from './ConnectionsPanel.vue';import UIcon from '../../skills/atoms/UIcon.vue';
const platform=ref(''),apps=ref<any[]>([]),records=ref<any[]>([]),activeKind=ref('bookmarks'),browser=ref('safari'),busy=ref(false),error=ref(''),message=ref('');
const route=useRoute(),router=useRouter();
const workspaceTabs=[{id:'google',label:'Google',icon:'cloud'},{id:'apple',label:'Apple',icon:'computer'},{id:'linux',label:'Linux',icon:'desktop_windows'},{id:'vault',label:'Vault',icon:'folder'}];
const workspace=computed(()=>workspaceTabs.some(t=>t.id===route.query.workspace)?String(route.query.workspace):'vault');
const collectionKind=computed(()=>['tasks','contacts','notes','calendar','mail'].includes(String(route.query.collection))?String(route.query.collection):'tasks');
const shell=useShellStore();
function openVault(){shell.setSidebarMode('vault');shell.setSidebarOpen(true);}
function chooseWorkspace(workspace:string){if(workspace==='vault')openVault();void router.replace({query:{...route.query,workspace}});}
function chooseCollection(collection:string){void router.replace({query:{...route.query,collection}});}
async function request(path:string,body?:object){const response=await fetch(`${UCORE_BASE}${path}`,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});if(!response.ok)throw Error((await response.text()).slice(0,240));return response.json();}
async function loadRecords(){const result=await request('/api/connections/records');records.value=result.records.filter((r:any)=>['bookmarks','reading_list'].includes(r.kind));}
async function importFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;busy.value=true;error.value='';try{if(file.size>2_000_000)throw Error('Choose an HTML export under 2 MB.');const result=await request('/api/snackbar/sync/browser/import',{html:await file.text(),source:browser.value});await loadRecords();message.value=`${result.imported} added · ${result.updated} updated. No browser settings were changed.`;}catch(e){error.value=e instanceof Error?e.message:'Import unavailable';}finally{busy.value=false;input.value='';}}
async function exportFile(){busy.value=true;try{const response=await fetch(`${UCORE_BASE}/api/snackbar/sync/browser/export`);if(!response.ok)throw Error('Export unavailable');const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download='udos-bookmarks.html';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error.value=e instanceof Error?e.message:'Export unavailable';}finally{busy.value=false;}}
async function markRead(record:any,read:boolean){try{await request('/api/connections/records',{...record,data:{...record.data,read}});await loadRecords();}catch(e){error.value=e instanceof Error?e.message:'Could not save reading state';}}
onMounted(async()=>{try{const data=await request('/api/apps');platform.value=data.platform;apps.value=data.apps;if(platform.value!=='macos')browser.value='firefox';await loadRecords();}catch(e){error.value=e instanceof Error?e.message:'Apps unavailable';}});
</script>
<style scoped>.apps-manager{display:grid;gap:20px;text-align:left;padding:16px}.apps-manager h2,.apps-manager h3,.apps-manager h4{margin:0 0 8px}.apps-manager p{margin:0 0 12px;color:var(--usx-color-on-surface-muted);font-size:var(--usx-font-size-sm);line-height:1.5}.app-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:8px 0}.usx-btn{display:inline-flex;align-items:center;gap:6px;min-height:32px;padding:4px 8px;margin:0}.apps-manager select{height:32px;margin:0;padding:4px 8px;border:1px solid var(--usx-color-border);background:var(--usx-color-surface);color:inherit;border-radius:var(--usx-radius-sm);box-shadow:none}#browser-export-file{position:absolute;width:1px;height:1px;opacity:0}.recommended-app{display:flex;gap:12px;align-items:start;justify-content:space-between;padding:12px 0;border-bottom:1px solid var(--usx-color-border)}.recommended-app>div{flex:1}.recommended-app small,.browser-link small{font-size:var(--usx-font-size-sm);color:var(--usx-color-on-surface-muted)}.browser-link{display:grid;gap:4px;padding:8px 0;border-bottom:1px solid var(--usx-color-border)}.browser-link label{display:flex;align-items:center;gap:8px;margin:0;font-size:var(--usx-font-size-sm)}.browser-link input{margin:0}.apps-manager [role=alert]{color:var(--usx-color-danger)}summary{cursor:pointer}@media(max-width:36rem){.recommended-app{flex-direction:column}}</style>
